window.OxMockSamples = {"arrays.hlsl":"#include \"@resources.hlsli\"\n\n// Resource arrays and array indexing: four terrain layers picked per texel by splat-map weights.\n// The STOCHASTIC uniform swaps the four-tap blend for one tap chosen by the weights, at the cost of\n// a single layer.\n\nTexture2D<F32x4> _layers[4];\nTexture2D<F32x4> _splat;\nSamplerState _sampler;\nRWTexture2D<F32x4> _output;\n\nstruct Terrain {\n    U32x2 res;\n    F32x2 tiling;\n};\n\nPUSH_CONSTANT Terrain _terrain;\n\nU32 hash(U32x2 p) {\n    U32 h = p.x * 0x8DA6B343 ^ p.y * 0xD8163841;\n    h ^= h >> 15;\n    h *= 0x2C1B3C6D;\n    h ^= h >> 12;\n    h *= 0x297A2D39;\n    h ^= h >> 15;\n    return h;\n}\n\n[[oxc::uniforms(B1 STOCHASTIC = false)]]\n[[oxc::uniforms(B1 STOCHASTIC = true)]]\n[shader(\"compute\")]\n[numthreads(8, 8, 1)]\nvoid mainArrays(U32x2 id : SV_DispatchThreadID) {\n\n    if (any(id >= _terrain.res))\n        return;\n\n    F32x2 uv = (F32x2(id) + 0.5) / F32x2(_terrain.res);\n\n    F32x4 weights = _splat.SampleLevel(_sampler, uv, 0);\n    weights /= max(weights.x + weights.y + weights.z + weights.w, 1e-4);\n\n    F32x2 tiled = uv * _terrain.tiling;\n    F32x4 c = 0;\n\n#ifdef $$STOCHASTIC\n    if ($$STOCHASTIC) {\n\n        F32 r = hash(id) * (1.0 / 4294967296.0);\n        F32x3 cdf = F32x3(weights.x, weights.x + weights.y, weights.x + weights.y + weights.z);\n        U32 pick = (U32)(r >= cdf.x) + (U32)(r >= cdf.y) + (U32)(r >= cdf.z);\n\n        c = _layers[NonUniformResourceIndex(pick)].SampleLevel(_sampler, tiled, 0);\n    }\n    else\n#endif\n    {\n        [unroll]\n        for (U32 i = 0; i < 4; ++i)\n            c += weights[i] * _layers[i].SampleLevel(_sampler, tiled, 0);\n    }\n\n    _output[id] = c;\n}\n","bindless.hlsl":"#include \"@resources.hlsli\"\n#include \"@buffer.hlsli\"\n\n// OxC3's bindless model: a resource is a U32 handle in a push constant, resolved through the big\n// descriptor arrays @resources.hlsli declares. No per-draw descriptor sets, no root signature juggling:\n// the same shader binds anything the frame created, on Vulkan and D3D12 alike.\n\nstruct DrawData {\n    U32 histogram;     // handle of a RWByteAddressBuffer\n    U32 texture;       // handle of a Texture2D\n    U32 smp;           // handle of a SamplerState, read by the DynamicSamplers permutation only\n    U32 binCount;\n};\n\nPUSH_CONSTANT DrawData _draw;\n\n// A sampler known when the layout is built is a static sampler: it costs no descriptor set and no\n// sampler heap, so it is the permutation to prefer whenever the sampler does not change per draw.\nSamplerState _sampler;\n\n// vendor narrows which GPUs may run this binary (metadata, no extra compiles); binary narrows which\n// backends it is emitted for, ANDed with -compile-output.\n// Repeating [[oxc::extension]] compiles one permutation per set, in this order of preference: the\n// first needs no extension and samples through the static sampler above; the second asks for the\n// bindless sampler array, which owns a whole descriptor set on SPIR-V and forces a sampler heap on\n// both backends, so only a shader that must pick its sampler per draw should pay for it. The body\n// switches on the define the extension sets.\n[[oxc::model(\"6.6\")]]\n[[oxc::vendor(\"NV\", \"AMD\")]]\n[[oxc::binary(\"spv\", \"dxil\")]]\n[[oxc::extension()]]\n[[oxc::extension(\"DynamicSamplers\")]]\n[[oxc::stage(\"compute\")]]\n[numthreads(64, 1, 1)]\nvoid main(U32 i : SV_DispatchThreadID) {\n\n    if (i >= _draw.binCount)\n        return;\n\n    F32x2 uv = F32x2(F32(i) / F32(_draw.binCount), 0.5);\n#ifdef __OXC_EXT_DYNAMICSAMPLERS\n    F32x4 texel = texture2DUniform(_draw.texture).SampleLevel(samplerUniform(_draw.smp), uv, 0);\n#else\n    F32x4 texel = texture2DUniform(_draw.texture).SampleLevel(_sampler, uv, 0);\n#endif\n\n    // Luma-keyed histogram. Threads share bins, so the increment has to be atomic.\n    U32 bin = min(U32(dot(texel.rgb, F32x3(0.2126, 0.7152, 0.0722)) * F32(_draw.binCount)), _draw.binCount - 1);\n    rwBufferUniform(_draw.histogram).InterlockedAdd(bin * 4, 1);\n}\n","broken.hlsl":"#include \"@types.hlsli\"\n\n// A file mid-edit, with one mistake of every shape the compiler can outline through. It does not\n// compile, but the Symbols tab, hover and completion keep working on every declaration below.\n\nstruct Light {\n    F32x3 pos;\n    Radiance intensity;                     // undefined type on a member\n    F32 range;\n};\n\nstruct Node {\n    Node next;                              // a type that contains itself\n    F32 weight;\n};\n\nstruct Params { F32 exposure; };\nstruct Params { F32 gamma; };               // duplicate definition\n\nStructuredBuffer<Light> _lights;\nRWTexture2D<F32x4> _output;\n\nF32 attenuate(Distance d, F32 range) {      // undefined type on a parameter\n    return saturate(1 - d / range);\n}\n\n[shader(\"compute\")]\n[numthreads(8, 8, 1)]\nvoid main(U32x3 id : SV_DispatchThreadID) {\n\n    Light light = _lights[0];\n    F32 a = attenuate(length(light.pos), light.range);\n    F32x3 c = shade(light, a);              // call to an undeclared function\n    _output[id.xy] = F32x4(c, 1) + position;    // undeclared identifier\n    F32x3 unfinished = light.               // half-typed member access\n}\n","coop_vec.hlsl":"#include \"@types.hlsli\"\n#include \"@extensions.hlsli\"\n\n// Cooperative vectors: the matrix times vector at the heart of neural inference as one hardware op.\n// Two layers of a tiny MLP, F16 weights with a bias, a ReLU, then FP8 weights for the second layer,\n// the shape a neural texture decoder or a learned BRDF runs per pixel. DXIL lowers each step to\n// __builtin_MatVecMul through dx/linalg.h, SPIR-V to SPV_NV_cooperative_vector, from one macro.\n// The vector lives in a buffer between steps, which is what the macros work on.\n\nOXC_COOPVEC_MATRIX_BUFFER(_layer1);     // 4x4 F16\nOXC_COOPVEC_VECTOR_BUFFER(_bias1);\nOXC_COOPVEC_MATRIX_BUFFER(_layer2);     // 4x4 FP8 e4m3, a quarter of the bytes of layer 1\nOXC_COOPVEC_VECTOR_BUFFER(_activations);\n\n[[oxc::model(\"6.10\")]]\n[[oxc::extension(\"CoopVec\", \"CoopFP8\", \"16BitTypes\")]]\n[shader(\"compute\")]\n[numthreads(1, 1, 1)]\nvoid main() {\n\n    OXC_COOPVEC_MATVEC_BIAS_4X4_F16(_layer1, 0, 8, _bias1, _activations);\n\n    [unroll]\n    for (U32 i = 0; i < 4; ++i)\n        _activations[0].data[i] = max(_activations[0].data[i], (float16_t) 0);\n\n    OXC_COOPVEC_MATVEC_FP8W_4X4_F16(_layer2, 0, _activations);\n}\n","descriptor_heap.hlsl":"#include \"@types.hlsli\"\n\n// Full bindless, SM6.6 style: resources come straight off the descriptor heap by index, no descriptor\n// layout at all, through ResourceDescriptorHeap/SamplerDescriptorHeap.\n//\n// DXIL only for now, hence [[oxc::binary(\"dxil\")]]: the compiler refuses the SPIRV leg of any\n// DescriptorHeap shader until DXC's SPV_EXT_descriptor_heap lowering is integrated upstream (see\n// Compiler_buildCompileArgs), and the annotation is what lets the DXIL leg compile alone. The annotation comes\n// off, and the output UAV can move onto the heap too, once that lands.\n\nRWStructuredBuffer<F32x4> _out : register(u0);\n\nstruct Blur {\n    U32x2 res;\n};\n\nPUSH_CONSTANT Blur _blur;\n\n// $BLUR_TAPS is a preprocessor define: each [[oxc::defines]] annotation is one full variant compile,\n// so this oiSH carries a 5-tap and a 9-tap binary of the same entrypoint.\n\n[[oxc::binary(\"dxil\")]]\n[[oxc::extension(\"DescriptorHeap\")]]\n[[oxc::model(\"6.6\")]]\n[[oxc::defines(\"BLUR_TAPS\" = \"5\")]]\n[[oxc::defines(\"BLUR_TAPS\" = \"9\")]]\n[[oxc::stage(\"compute\")]]\n[numthreads(8, 8, 1)]\nvoid main(U32x2 id : SV_DispatchThreadID) {\n\n    if (any(id >= _blur.res))\n        return;\n\n    Texture2D<F32x4> src = ResourceDescriptorHeap[0];\n    SamplerState samp = SamplerDescriptorHeap[0];\n\n    // $BLUR_TAPS only exists per variant, so the annotation-scan pass needs the guarded fallback.\n#ifdef $BLUR_TAPS\n    static const I32 taps = $BLUR_TAPS;\n#else\n    static const I32 taps = 5;\n#endif\n\n    F32x2 uv = (F32x2(id) + 0.5) / F32x2(_blur.res);\n    F32x4 acc = 0;\n\n    [unroll]\n    for (I32 i = 0; i < taps; ++i)\n        acc += src.SampleLevel(samp, uv + F32x2(i - taps / 2, 0) / F32(_blur.res.x), 0);\n\n    _out[id.y * _blur.res.x + id.x] = acc / taps;\n}\n","enums.hlsl":"#include \"@resources.hlsli\"\n\nenum class Mode : U32 { Off = 0, Linear = 1, Cubic = 2 };\n\ntypedef F32x4 Color;\n\nstruct Material {\n    Color albedo;\n    F32 roughness;\n    U32 flags;\n};\n\nStructuredBuffer<Material> _materials;\nRWStructuredBuffer<Color> _out;\ncbuffer Params { U32 materialCount; U32 modeRaw; };\n\n// Roughness darkens the albedo: not at all, proportionally, or with a cubic falloff.\nColor shade(Material m, Mode mode) {\n\n    switch (mode) {\n        case Mode::Linear:  return m.albedo * (1 - m.roughness);\n        case Mode::Cubic:   return m.albedo * pow(1 - m.roughness, 3);\n        default:            return m.albedo;\n    }\n}\n\n[[oxc::stage(\"compute\")]]\n[numthreads(64, 1, 1)]\nvoid mainEnums(U32 i : SV_DispatchThreadID) {\n\n    if (i >= materialCount)\n        return;\n\n    _out[i] = shade(_materials[i], (Mode) modeRaw);\n}\n","include/light.hlsli":"#pragma once\n#include \"@types.hlsli\"\n\nstruct Light {\n    \n    F32x3 position;\n    F32   radius;\n\n    F32x3 color;\n    F32   intensity;\n};\n\nF32x3 shadeLight(Light l, F32x3 cam) {\n    F32x3 d = l.position - cam;\n    return l.color * l.intensity / (1.0 + dot(d, d));\n}\n","interfaces.hlsl":"#include \"@types.hlsli\"\n\n// Interfaces and inheritance reflect into the oiSR type graph: the Symbols tab records which interface a\n// struct implements and which base it extends, so go-to-definition works across the hierarchy.\n\ninterface IArea {\n    F32 area();\n};\n\nstruct Shape {\n    F32x2 size;\n};\n\nstruct Rect : Shape, IArea {\n    F32 area() { return size.x * size.y; }\n};\n\nstruct Circle : Shape, IArea {\n    F32 area() { return 3.14159265 * size.x * size.x; }\n};\n\nRWStructuredBuffer<F32> _areas;\n\nstruct Shapes {\n    U32 count;\n};\n\nPUSH_CONSTANT Shapes _shapes;\n\ntemplate<typename T>\nF32 areaOf(F32x2 size) {\n    T t;\n    t.size = size;\n    return t.area();\n}\n\n[[oxc::stage(\"compute\")]]\n[numthreads(1, 1, 1)]\nvoid main(U32 id : SV_DispatchThreadID) {\n\n    if (id >= _shapes.count)\n        return;\n\n    _areas[id * 2 + 0] = areaOf<Rect>(F32x2(3, 4));\n    _areas[id * 2 + 1] = areaOf<Circle>(F32x2(2, 2));\n}\n","lighting.hlsl":"#include \"@types.hlsli\"\n#include \"include/light.hlsli\"\n\ncbuffer Globals {\n    F32x4x4 viewProj;\n    F32x3 cameraPos;\n    U32 lightCount;\n    U32x2 res;\n};\n\nStructuredBuffer<Light> _lights;\nTexture2D<F32x4> _albedo;\nSamplerState _sampler;   // never sampled, so Reflection marks it unused\nRWTexture2D<F32x4> _output;\n\n[[oxc::uniforms(U32 MAX_LIGHTS = 64)]]\n[shader(\"compute\")]\n[numthreads(8, 8, 1)]\nvoid main(U32x3 id : SV_DispatchThreadID) {\n\n    if (any(id.xy >= res))\n        return;\n\n    F32x4 c = _albedo.Load(int3(id.xy, 0));\n\n    U32 count = lightCount;\n#ifdef $$MAX_LIGHTS\n    count = min(count, $$MAX_LIGHTS);\n#endif\n\n    // Every light per texel is the example, not the advice; a renderer culls or clusters first.\n    for (U32 i = 0; i < count; ++i)\n        c.rgb += shadeLight(_lights[i], cameraPos);\n\n    _output[id.xy] = c;\n}\n","mesh.hlsl":"#include \"@types.hlsli\"\n\n// A mesh stage replaces the whole vertex chain: this one emits a full-screen quad and the pixel\n// stage shades it, which is the smallest complete mesh pipeline.\n\nstruct MeshOut {\n    F32x4 pos : SV_Position;\n    F32x2 uv : TEXCOORD0;\n};\n\n[[oxc::stage(\"mesh\")]]\n[outputtopology(\"triangle\")]\n[numthreads(4, 1, 1)]\nvoid mainMesh(\n    U32 tid : SV_GroupThreadID,\n    out vertices MeshOut verts[4],\n    out indices U32x3 tris[2]\n) {\n    SetMeshOutputCounts(4, 2);\n\n    const F32x2 uv = F32x2(tid & 1, tid >> 1);\n    verts[tid].pos = F32x4(uv * 2 - 1, 0, 1);\n    verts[tid].uv = uv;\n\n    if (tid < 2)\n        tris[tid] = tid ? U32x3(1, 3, 2) : U32x3(0, 1, 2);\n}\n\n[[oxc::stage(\"pixel\")]]\nF32x4 mainPixel(MeshOut i) : SV_Target {\n    return F32x4(i.uv, 0.5, 1);\n}\n","post.hlsl":"#include \"@types.hlsli\"\n\nstruct PostCmd {\n    F32x3 tint;\n    F32   exposure;\n};\n\nPUSH_CONSTANT PostCmd cmd;\n\nTexture2D<F32x4> _color;\nSamplerState     _sampler;\n\nstruct VSOut {\n    F32x4 pos : SV_Position;\n    F32x2 uv  : TEXCOORD0;\n};\n\n[[oxc::stage(\"vertex\")]]\nVSOut vsMain(U32 vid : SV_VertexID) {\n    VSOut o;\n    o.uv  = F32x2((vid << 1) & 2, vid & 2);\n    o.pos = F32x4(o.uv * F32x2(2, -2) + F32x2(-1, 1), 0, 1);\n    return o;\n}\n\n[[oxc::defines(\"TONEMAP_ACES\")]]\n[[oxc::defines()]]\n[[oxc::stage(\"pixel\")]]\nF32x4 psMain(VSOut i) : SV_Target {\n\n    F32x4 c = _color.SampleLevel(_sampler, i.uv, 0);\n    c.rgb *= cmd.exposure * cmd.tint;\n\n#ifdef $TONEMAP_ACES\n    // ACES filmic curve fit, Narkowicz 2015.\n    c.rgb = saturate((c.rgb * (2.51 * c.rgb + 0.03)) / (c.rgb * (2.43 * c.rgb + 0.59) + 0.14));\n#endif\n\n    return c;\n}\n","tess.hlsl":"#include \"@types.hlsli\"\n\n// Tessellation: vertex and hull carry object space control points, the domain stage interpolates and\n// only then projects, so the new vertices land on the surface rather than on a projected triangle.\n\nstruct Transform {\n    F32x4x4 mvp;\n    F32     tess;\n};\n\nPUSH_CONSTANT Transform _transform;\n\nstruct ControlPoint { F32x3 pos : POSITION; F32x2 uv : TEXCOORD0; };\nstruct VSOut { F32x4 pos : SV_Position; F32x2 uv : TEXCOORD0; };\nstruct PatchConst { F32 edges[3] : SV_TessFactor; F32 inner : SV_InsideTessFactor; };\n\n[[oxc::stage(\"vertex\")]]\nControlPoint mainVert(F32x3 pos : POSITION, F32x2 uv : TEXCOORD0) {\n    ControlPoint o;\n    o.pos = pos;\n    o.uv = uv;\n    return o;\n}\n\nPatchConst constants(InputPatch<ControlPoint, 3> patch) {\n    // A factor of 0 or less culls the patch, so a zeroed push constant would draw nothing.\n    F32 tess = max(_transform.tess, 1);\n    PatchConst c;\n    c.edges[0] = c.edges[1] = c.edges[2] = tess;\n    c.inner = tess;\n    return c;\n}\n\n[[oxc::stage(\"hull\")]]\n[domain(\"tri\")]\n[partitioning(\"fractional_odd\")]\n[outputtopology(\"triangle_cw\")]\n[outputcontrolpoints(3)]\n[patchconstantfunc(\"constants\")]\nControlPoint mainHull(InputPatch<ControlPoint, 3> patch, U32 i : SV_OutputControlPointID) {\n    return patch[i];\n}\n\n[[oxc::stage(\"domain\")]]\n[domain(\"tri\")]\nVSOut mainDomain(PatchConst c, F32x3 bary : SV_DomainLocation, const OutputPatch<ControlPoint, 3> patch) {\n    F32x3 pos = patch[0].pos * bary.x + patch[1].pos * bary.y + patch[2].pos * bary.z;\n    VSOut o;\n    o.pos = mul(_transform.mvp, F32x4(pos, 1));\n    o.uv = patch[0].uv * bary.x + patch[1].uv * bary.y + patch[2].uv * bary.z;\n    return o;\n}\n\n[[oxc::stage(\"pixel\")]]\nF32x4 mainPixel(VSOut i) : SV_Target { return F32x4(i.uv, 0, 1); }\n","trace.hlsl":"#include \"@types.hlsli\"\n\n// A whole ray tracing pipeline in one lib: raygen, closest hit and miss compile to DXR on DXIL and\n// SPV_KHR_ray_tracing on SPIR-V, and land in one oiSH with a binary per entrypoint.\n\nstruct Payload { F32x3 color; F32 hitT; };\n\nRaytracingAccelerationStructure _tlas;\nRWTexture2D<F32x4>              _out;\n\n[shader(\"miss\")]\nvoid miss(inout Payload p) {\n    // Sky: the ray direction itself, remapped to a color.\n    p.color = WorldRayDirection() * 0.5 + 0.5;\n    p.hitT = -1;\n}\n\n[shader(\"closesthit\")]\nvoid hit(inout Payload p, BuiltInTriangleIntersectionAttributes attr) {\n    // Barycentrics as color: the classic first triangle.\n    p.color = F32x3(1 - attr.barycentrics.x - attr.barycentrics.y, attr.barycentrics);\n    p.hitT = RayTCurrent();\n}\n\n// Two extension sets on one entry: the lib compiles once per set, so this oiSH carries two rgen\n// binaries and deriving a pipeline asks which one with -entry, exactly like the CLI would.\n[[oxc::model(\"6.5\")]]\n[[oxc::extension(\"RayQuery\")]]\n[[oxc::extension()]]\n[shader(\"raygeneration\")]\nvoid rgen() {\n    U32x2 id = DispatchRaysIndex().xy;\n    F32x2 uv = (F32x2(id) + 0.5) / F32x2(DispatchRaysDimensions().xy);\n\n    RayDesc ray;\n    ray.Origin = F32x3(uv * 2 - 1, -1);\n    ray.Direction = F32x3(0, 0, 1);\n    ray.TMin = 0;\n    ray.TMax = 1e6;\n\n    Payload p = (Payload)0;\n    TraceRay(_tlas, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);\n\n    _out[id] = F32x4(p.color, 1);\n}\n","trace_inline.hlsl":"#include \"@types.hlsli\"\n\n// Inline ray tracing: a compute shader asks the acceleration structure directly through RayQuery,\n// with no ray tracing pipeline, payload or shader table. One shadow ray per texel.\n\nRaytracingAccelerationStructure _tlas;\nTexture2D<F32x4>                _position;      // world position per texel, w = 0 where there is none\nTexture2D<F32x4>                _geoNormal;     // geometric normal per texel, not the shading one\nRWTexture2D<F32>                _shadow;\n\nstruct Sun {\n    F32x3 dir;\n    U32   pad;\n    U32x2 res;\n};\n\nPUSH_CONSTANT Sun _sun;\n\n// Where a secondary ray starts (RT Gems 1 ch. 6, Waechter and Binder): the origin moves along the\n// geometric normal by a fixed number of ULPs of the position itself, so the margin scales with the\n// distance from the world origin. A constant offset is too big near the origin and too small far away.\nF32x3 offsetRay(F32x3 p, F32x3 geoNormal) {\n    \n    static const F32 ORIGIN = 1.0 / 32.0;\n    static const F32 FLOAT_SCALE = 1.0 / 65536.0;\n    static const F32 INT_SCALE = 256.0;\n\n    // Stepping the mantissa away from the surface adds for a positive coordinate and subtracts for a\n    // negative one, since the float encoding grows away from zero in both directions.\n    const I32x3 ofI = I32x3(geoNormal * INT_SCALE);\n    const F32x3 pI = asfloat(asint(p) + select(p < 0, -ofI, ofI));\n\n    // Near the origin the float branch scales with the dominant magnitude, so a near zero component of\n    // a hit far along the ray still clears its true error.\n    const F32 floatScale = FLOAT_SCALE * max(1.0, max(max(abs(p.x), abs(p.y)), abs(p.z)));\n    return select(abs(p) < ORIGIN, p + geoNormal * floatScale, pI);\n}\n\n[[oxc::model(\"6.5\")]]\n[[oxc::extension(\"RayQuery\")]]\n[shader(\"compute\")]\n[numthreads(8, 8, 1)]\nvoid main(U32x2 id : SV_DispatchThreadID) {\n\n    if (any(id >= _sun.res))\n        return;\n\n    F32x4 p = _position[id];\n\n    if (p.w == 0) {\n        _shadow[id] = 1;\n        return;\n    }\n\n    F32x3 geoNormal = _geoNormal[id].xyz;\n\n    RayDesc ray;\n    ray.Origin    = offsetRay(p.xyz, geoNormal);\n    ray.Direction = _sun.dir;\n    ray.TMin      = 0;\n    ray.TMax      = 1e6;\n\n    // Any hit is enough for a shadow, so the query may stop at the first one and never sort.\n    RayQuery<RAY_FLAG_ACCEPT_FIRST_HIT_AND_END_SEARCH | RAY_FLAG_FORCE_OPAQUE> query;\n    query.TraceRayInline(_tlas, RAY_FLAG_NONE, 0xFF, ray);\n    query.Proceed();\n\n    _shadow[id] = query.CommittedStatus() == COMMITTED_NOTHING ? 1 : 0;\n}\n","trace_ser.hlsl":"#include \"@types.hlsli\"\n#include \"@extensions.hlsli\"\n\n// Shader execution reordering: TraceRay split into record, reorder hint and invoke. Between the\n// record and the invoke a device that reorders regroups lanes by what they hit, so the hit shaders\n// run on coherent waves; a device that does not simply continues, with the same result.\n// SM 6.9 also requires the payload to say who reads and writes each field.\n\nstruct [raypayload] Payload {\n    F32x3 color : read(caller) : write(closesthit, miss);\n};\n\nRaytracingAccelerationStructure _tlas;\nRWTexture2D<F32x4>              _out;\n\n[[oxc::model(\"6.9\")]]\n[shader(\"miss\")]\nvoid miss(inout Payload p) {\n    p.color = WorldRayDirection() * 0.5 + 0.5;\n}\n\n[[oxc::model(\"6.9\")]]\n[shader(\"closesthit\")]\nvoid hit(inout Payload p, BuiltInTriangleIntersectionAttributes attr) {\n    p.color = F32x3(1 - attr.barycentrics.x - attr.barycentrics.y, attr.barycentrics);\n}\n\n// Miss and closest hit compile without RayReorder, where the hit object types do not exist, so the\n// raygen vanishes from their parse; the annotation pass sees every extension and still registers it.\n#ifdef __OXC_EXT_RAYREORDER\n\n[[oxc::model(\"6.9\")]]\n[[oxc::extension(\"RayReorder\")]]\n[shader(\"raygeneration\")]\nvoid rgen() {\n\n    U32x2 id = DispatchRaysIndex().xy;\n    F32x2 uv = (F32x2(id) + 0.5) / F32x2(DispatchRaysDimensions().xy);\n\n    RayDesc ray;\n    ray.Origin    = F32x3(uv * 2 - 1, -1);\n    ray.Direction = F32x3(0, 0, 1);\n    ray.TMin      = 0;\n    ray.TMax      = 1e6;\n\n    OXC_RAYPAYLOAD Payload p;\n    p.color = 0;\n\n    OXC_HITOBJECT(hitObj);\n    oxc::HitObject_TraceRay(hitObj, _tlas, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);\n    oxc::MaybeReorderThread(hitObj);\n    oxc::HitObject_Invoke(hitObj, p);\n\n    _out[id] = F32x4(p.color, 1);\n}\n\n#endif\n","wave.hlsl":"#include \"@types.hlsli\"\n\n// Wave intrinsics: stream compaction without a prefix sum pass. Every lane decides whether to keep\n// its element, the wave counts the keepers and hands each one a slot, and one lane per wave reserves\n// the wave's block with a single atomic instead of one per element.\n\nStructuredBuffer<F32x4>   _particles;   // xyz position, w remaining lifetime\nRWStructuredBuffer<F32x4> _alive;\nRWByteAddressBuffer       _aliveCount;\n\nstruct Compact {\n    U32 count;\n};\n\nPUSH_CONSTANT Compact _compact;\n\n[[oxc::model(\"6.6\")]]\n[[oxc::extension(\"SubgroupOperations\")]]\n[shader(\"compute\")]\n[numthreads(64, 1, 1)]\nvoid main(U32 id : SV_DispatchThreadID) {\n\n    // Lanes past the end stay in the wave so the counts below see every lane; they just keep nothing.\n    bool keep = false;\n\n    if (id < _compact.count)\n        keep = _particles[id].w > 0;\n\n    U32 keptInWave = WaveActiveCountBits(keep);\n    U32 slot       = WavePrefixCountBits(keep);\n\n    U32 base = 0;\n\n    if (WaveIsFirstLane() && keptInWave > 0)\n        _aliveCount.InterlockedAdd(0, keptInWave, base);\n\n    base = WaveReadLaneFirst(base);\n\n    if (keep)\n        _alive[base + slot] = _particles[id];\n}\n"};
